static int bucketIndex(Object key, int tableLength) {
    int h = key.hashCode();
    int hash = h ^ (h >>> 16);        // spread the high bits into the low bits
    return (tableLength - 1) & hash;  // same as hash % tableLength, because the length is a power of two
}

