import java.util.List;

class Util {
    static <T> T firstOf(List<T> list) {
        return list.get(0);
    }

    static <T> void swap(T[] array, int i, int j) {
        T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

