        int firstNumber = Util.firstOf(List.of(10, 20, 30));        // T is Integer
        System.out.println(firstName + " " + firstNumber);

        Integer[] numbers = {1, 2, 3};
        Util.swap(numbers, 0, 2);
        System.out.println(java.util.Arrays.toString(numbers));
    }
}

// Output:
