class InsufficientFundsException extends Exception {
    private final long missing;

    InsufficientFundsException(long missing) {
        super("Missing " + missing + " to complete the payment");
        this.missing = missing;
    }

    long missing() { return missing; }
}

class Wallet {
    private long balance = 500;

    void pay(long amount) throws InsufficientFundsException {
        if (amount > balance) throw new InsufficientFundsException(amount - balance);
        balance -= amount;
    }
}

class Demo {
    public static void main(String[] args) {
        Wallet wallet = new Wallet();
        try {
            wallet.pay(800);
        } catch (InsufficientFundsException e) {
            System.out.println(e.getMessage());
            System.out.println("Top up at least " + e.missing());
        }
    }
}

