        try {
            return Integer.parseInt(a) / Integer.parseInt(b);
        } catch (NumberFormatException | ArithmeticException e) {   // same handling for both
            System.out.println("Cannot calculate: " + e.getMessage());
            throw e;                                                  // log it, then let the caller know
        }
    }

    public static void main(String[] args) {
        System.out.println(divide("10", "2"));
        for (String[] pair : new String[][] {{"10", "0"}, {"ten", "2"}}) {
            try {
                divide(pair[0], pair[1]);
            } catch (RuntimeException e) {
                System.out.println("caller saw " + e.getClass().getSimpleName());
            }
        }
    }
}

