final class Money {
    private final long amount;
    private final String currency;

    Money(long amount, String currency) {
        this.amount = amount;
        this.currency = currency;
    }

    Money plus(Money other) {
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("Different currencies");
        return new Money(amount + other.amount, currency);     // a new object, the old ones stay unchanged
    }

    @Override public String toString() { return amount + " " + currency; }
}

class Demo {
    public static void main(String[] args) {
        Money a = new Money(500, "INR");
        Money b = new Money(250, "INR");
        Money total = a.plus(b);
        System.out.println(a + " + " + b + " = " + total);
        System.out.println("a is still " + a);
    }
}

// Output:
// 500 INR + 250 INR = 750 INR
// a is still 500 INR

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class Team {
    private final List<String> members;

    Team(List<String> members) {
        this.members = new ArrayList<>(members);               // copy on the way in
    }

    List<String> members() {
        return Collections.unmodifiableList(members);          // read-only view on the way out
    }
}

class Demo {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Asha", "Ravi"));
        Team team = new Team(names);

        names.add("Hacker");                                    // the caller changes its own list
        System.out.println(team.members());                     // the team is not affected

        try {
            team.members().add("Hacker");
        } catch (UnsupportedOperationException e) {
            System.out.println("cannot change the team from outside");
        }
    }
}

// Output:
// [Asha, Ravi]
// cannot change the team from outside

