        return switch (shape) {
            case Point(int x, int y) -> "point at " + x + "," + y;
            case Line(Point(var x1, var y1), Point(var x2, var y2))       // nested pattern
                    -> "line from " + x1 + "," + y1 + " to " + x2 + "," + y2;
            default -> "unknown";
        };
