/// A shopping cart.
///
/// Features:
/// - adds items
/// - calculates the **total**
///
/// See [Item] for the item type.
class Cart {
    private int total;

    /// Adds an item and returns the new total.
    ///
    /// @param price the price of the item
    /// @return the total after adding it
