class Email {
    private final String address;

    Email(String address) { this.address = address.toLowerCase(); }

    @Override
    public boolean equals(Object other) {
        if (this == other) return true;                      // reflexive
        if (!(other instanceof Email that)) return false;    // handles null and other types
        return address.equals(that.address);
    }

    @Override
    public int hashCode() { return address.hashCode(); }     // always override both together
}

