import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

class Demo {
    public static void main(String[] args) throws InterruptedException {
        CountDownLatch done = new CountDownLatch(3);
        Semaphore permits = new Semaphore(2);                 // at most 2 at a time
        AtomicInteger running = new AtomicInteger();
        AtomicInteger maxRunning = new AtomicInteger();

        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                try {
                    permits.acquire();
                    int now = running.incrementAndGet();
                    maxRunning.accumulateAndGet(now, Math::max);
                    Thread.sleep(100);
                    running.decrementAndGet();
                    permits.release();
                } catch (InterruptedException ignored) { }
                done.countDown();                             // one step finished
            }).start();
        }

        done.await();                                         // waits until the count reaches zero
        System.out.println("all workers finished, at most " + maxRunning.get() + " ran together");
    }
}

// Output:
// all workers finished, at most 2 ran together

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

class Demo {
    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(2);        // holds at most 2 items
        int[] sum = {0};

        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 5; i++) queue.put(i);                  // waits if the queue is full
                queue.put(-1);                                              // a "stop" marker
            } catch (InterruptedException ignored) { }
        });

        Thread consumer = new Thread(() -> {
            try {
                for (int item = queue.take(); item != -1; item = queue.take()) sum[0] += item;   // waits if empty
            } catch (InterruptedException ignored) { }
        });

        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.println("sum of consumed items: " + sum[0]);
    }
}

