                1, 2,                                            // core 1 thread, up to 2 threads
                60, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1),                     // the queue holds 1 waiting task
                new ThreadPoolExecutor.AbortPolicy());           // throw when everything is full

        Runnable slow = () -> { try { Thread.sleep(300); } catch (InterruptedException ignored) { } };

