import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class Demo {
    static void shutdown(ExecutorService pool) throws InterruptedException {
        pool.shutdown();                                          // 1. stop accepting new tasks
        if (!pool.awaitTermination(1, TimeUnit.SECONDS)) {        // 2. give running tasks time to finish
            pool.shutdownNow();                                   // 3. interrupt whatever is still running
            pool.awaitTermination(1, TimeUnit.SECONDS);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        pool.submit(() -> System.out.println("quick task done"));
        pool.submit(() -> {
            try { Thread.sleep(10_000); }                          // a task that is too slow
            catch (InterruptedException e) { System.out.println("slow task was interrupted"); }
        });

        Thread.sleep(100);
        shutdown(pool);
        System.out.println("terminated: " + pool.isTerminated());
    }
}

// Output:
// quick task done
// slow task was interrupted
// terminated: true

import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

class SumTask extends RecursiveTask<Long> {
    private final int[] numbers;
    private final int from, to;

    SumTask(int[] numbers, int from, int to) { this.numbers = numbers; this.from = from; this.to = to; }

    @Override
    protected Long compute() {
        if (to - from <= 10_000) {                               // small enough: just add them
            long sum = 0;
            for (int i = from; i < to; i++) sum += numbers[i];
            return sum;
        }
        int middle = (from + to) / 2;
        SumTask left = new SumTask(numbers, from, middle);
        SumTask right = new SumTask(numbers, middle, to);
        left.fork();                                             // run the left half in parallel
        return right.compute() + left.join();                    // do the right half here, then combine
    }
}

class Demo {
    public static void main(String[] args) {
        int[] numbers = new int[1_000_000];
        java.util.Arrays.fill(numbers, 1);

        long total = ForkJoinPool.commonPool().invoke(new SumTask(numbers, 0, numbers.length));
        System.out.println(total);
    }
}

// Output:
// 1000000

