import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;

class Demo {
    public static void main(String[] args) {
        long before = totalCollections();

        for (int i = 0; i < 3_000_000; i++) {
            byte[] temporary = new byte[1024];            // short-lived object: garbage right after this loop turn
        }

        long after = totalCollections();
        System.out.println("the collector ran while we created garbage: " + (after > before));
    }

    static long totalCollections() {
        long total = 0;
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            total += gc.getCollectionCount();
        }
        return total;
    }
}

