import java.util.Map;

class Demo {
    static final List<byte[]> leaky = new ArrayList<>();     // static: reachable for the whole run, never cleared

    static class BoundedCache<K, V> extends LinkedHashMap<K, V> {
        private final int max;
        BoundedCache(int max) { super(16, 0.75f, true); this.max = max; }
        @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) { return size() > max; }
    }

    public static void main(String[] args) {
        for (int i = 0; i < 1_000; i++) leaky.add(new byte[1024]);   // every item stays reachable: this grows forever
        System.out.println("leaky list size: " + leaky.size());

        BoundedCache<Integer, byte[]> cache = new BoundedCache<>(100);
        for (int i = 0; i < 1_000; i++) cache.put(i, new byte[1024]);
        System.out.println("bounded cache size: " + cache.size());   // old entries were removed
    }
}

// Output:
// leaky list size: 1000
// bounded cache size: 100

class Demo {
    static int depth = 0;

    static void recurse() {
        depth++;
        recurse();                         // no stop condition: each call adds a frame to the stack
    }

    public static void main(String[] args) {
        try {
            recurse();
        } catch (StackOverflowError e) {
            System.out.println("stack ran out of space, reached a depth above 1000: " + (depth > 1000));
        }
        // a bigger stack for deep but valid recursion: java -Xss2m ...
    }
}

// Output:
// stack ran out of space, reached a depth above 1000: true

