import java.util.List;
import java.util.Map;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.stereotype.Component;

interface DiscountRule { int apply(int price); }

@Component("student")
class StudentRule implements DiscountRule { public int apply(int price) { return price - 10; } }

@Component("festival")
class FestivalRule implements DiscountRule { public int apply(int price) { return price - 5; } }

@Component
class PriceCalculator {
    private final List<DiscountRule> rules;
    private final Map<String, DiscountRule> byName;

    PriceCalculator(List<DiscountRule> rules, Map<String, DiscountRule> byName) {   // every implementation
        this.rules = rules;
        this.byName = byName;
    }

    int afterAll(int price) {
        for (DiscountRule rule : rules) price = rule.apply(price);
        return price;
    }

    int afterOne(String name, int price) { return byName.get(name).apply(price); }
}

@ComponentScan
class Demo {
    public static void main(String[] args) {
        try (var context = new AnnotationConfigApplicationContext(Demo.class)) {
            PriceCalculator calculator = context.getBean(PriceCalculator.class);
            System.out.println(calculator.afterAll(100));              // both rules applied
            System.out.println(calculator.afterOne("student", 100));   // one rule picked by bean name
        }
    }
}

// Output:
// 85
// 90

import org.springframework.beans.BeansException;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

class OrderService {
    OrderService(InvoiceService invoices) { }       // needs InvoiceService...
}

class InvoiceService {
    InvoiceService(OrderService orders) { }         // ...which needs OrderService: a circle
}

class PricingRules { }                              // the fix: both depend on a third class instead

class OrderService2 { OrderService2(PricingRules rules) { } }
class InvoiceService2 { InvoiceService2(PricingRules rules) { } }

@Configuration
class Circular {
    @Bean OrderService orders(InvoiceService invoices) { return new OrderService(invoices); }
    @Bean InvoiceService invoices(OrderService orders) { return new InvoiceService(orders); }
}

@Configuration
class Fixed {
    @Bean PricingRules rules() { return new PricingRules(); }
    @Bean OrderService2 orders(PricingRules rules) { return new OrderService2(rules); }
    @Bean InvoiceService2 invoices(PricingRules rules) { return new InvoiceService2(rules); }
}

class Demo {
    public static void main(String[] args) {
        try (var context = new AnnotationConfigApplicationContext(Circular.class)) {
            System.out.println("started");
        } catch (BeansException e) {
            System.out.println("circular: " + e.getClass().getSimpleName());
        }
        try (var context = new AnnotationConfigApplicationContext(Fixed.class)) {
            System.out.println("fixed: started");
        }
    }
}

// Output:
// circular: UnsatisfiedDependencyException
// fixed: started

