import java.util.concurrent.CountDownLatch;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Async;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.stereotype.Component;

record ReportRequested(String name) { }

@Component
class ReportListener {
    static final CountDownLatch done = new CountDownLatch(1);

    @Async                                                       // run on another thread
    @EventListener
    void on(ReportRequested event) {
        System.out.println("listener on another thread: " + !Thread.currentThread().getName().equals("main"));
        done.countDown();
    }
}

@ComponentScan
@EnableAsync
class Demo {
    public static void main(String[] args) throws Exception {
        try (var context = new AnnotationConfigApplicationContext(Demo.class)) {
            context.publishEvent(new ReportRequested("sales"));          // the context is itself a publisher
            System.out.println("publisher carries on without waiting");
            ReportListener.done.await();
        }
    }
}

// Output:
// publisher carries on without waiting
// listener on another thread: true

import javax.sql.DataSource;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;
import org.springframework.transaction.support.TransactionTemplate;

record OrderSaved(int id) { }

@Component
class EmailAfterCommit {
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    void on(OrderSaved event) { System.out.println("email sent for order " + event.id()); }
}

@Configuration
@EnableTransactionManagement
class Config {
    @Bean DataSource dataSource() { return new DriverManagerDataSource("jdbc:h2:mem:events"); }
    @Bean PlatformTransactionManager txManager(DataSource ds) { return new DataSourceTransactionManager(ds); }
    @Bean EmailAfterCommit email() { return new EmailAfterCommit(); }
}

class Demo {
    public static void main(String[] args) {
        try (var context = new AnnotationConfigApplicationContext(Config.class)) {
            TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));
            ApplicationEventPublisher publisher = context;

            tx.executeWithoutResult(status -> {
                publisher.publishEvent(new OrderSaved(1));
                System.out.println("order 1 saved, still inside the transaction");
            });                                                  // commit happens here, then the listener runs

            tx.executeWithoutResult(status -> {
                publisher.publishEvent(new OrderSaved(2));
                status.setRollbackOnly();                        // this one is rolled back: no email
                System.out.println("order 2 rolled back");
            });
        }
    }
}

// Output:
// order 1 saved, still inside the transaction
// email sent for order 1
// order 2 rolled back

