import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.ConfigurableApplicationContext;

@SpringBootApplication
class Demo {
    static String get(String port, String path) throws Exception {
        return HttpClient.newHttpClient().send(
                HttpRequest.newBuilder(URI.create("http://localhost:" + port + path)).build(),
                HttpResponse.BodyHandlers.ofString()).body();
    }

    public static void main(String[] args) throws Exception {
        System.setProperty("server.port", "0");
        System.setProperty("management.endpoints.web.exposure.include", "health");
        System.setProperty("management.endpoint.health.probes.enabled", "true");        // on by default in Kubernetes
        try (ConfigurableApplicationContext context = SpringApplication.run(Demo.class, args)) {
            String port = context.getEnvironment().getProperty("local.server.port");
            System.out.println("liveness:  " + get(port, "/actuator/health/liveness"));
            System.out.println("readiness: " + get(port, "/actuator/health/readiness"));
        }
    }
}

// Output:
// liveness:  {"status":"UP"}
// readiness: {"status":"UP"}

import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.stereotype.Component;

@Component
class PaymentGatewayHealth implements HealthIndicator {          // shows up as "paymentGateway" in the health report
    boolean reachable = true;

    @Override
    public Health health() {
        return reachable
                ? Health.up().withDetail("latencyMs", 42).build()
                : Health.down().withDetail("error", "connection refused").build();
    }
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            PaymentGatewayHealth gateway = context.getBean(PaymentGatewayHealth.class);
            System.out.println(gateway.health());
            gateway.reachable = false;
            System.out.println(gateway.health());
        }
    }
}

// Output:
// UP {latencyMs=42}
// DOWN {error=connection refused}

import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            MeterRegistry registry = context.getBean(MeterRegistry.class);

            registry.counter("orders.placed", "channel", "web").increment();          // a counter with a tag
            registry.counter("orders.placed", "channel", "web").increment();

            Timer timer = registry.timer("report.duration");
            timer.record(() -> { try { Thread.sleep(20); } catch (InterruptedException ignored) { } });

            System.out.println("orders: " + registry.get("orders.placed").tag("channel", "web").counter().count());
            System.out.println("timer calls: " + timer.count());
        }
    }
}

