import jakarta.validation.Constraint;
import jakarta.validation.ConstraintValidator;
import jakarta.validation.ConstraintValidatorContext;
import jakarta.validation.Payload;
import jakarta.validation.Validation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.annotation.ElementType;

@Constraint(validatedBy = Demo.StrongPasswordValidator.class)
@Target(ElementType.FIELD)
@Retention(RetentionPolicy.RUNTIME)
@interface StrongPassword {
    String message() default "needs a digit and an upper-case letter";
    Class<?>[] groups() default {};
    Class<? extends Payload>[] payload() default {};
}

class Account {
    @StrongPassword String password;
    Account(String password) { this.password = password; }
}

public class Demo {
    public static class StrongPasswordValidator implements ConstraintValidator<StrongPassword, String> {
        @Override
        public boolean isValid(String value, ConstraintValidatorContext context) {
            return value != null && value.chars().anyMatch(Character::isDigit) && value.chars().anyMatch(Character::isUpperCase);
        }
    }

    public static void main(String[] args) {
        var validator = Validation.buildDefaultValidatorFactory().getValidator();
        System.out.println(validator.validate(new Account("password")).size() + " violation for \"password\"");
        System.out.println(validator.validate(new Account("Passw0rd")).size() + " violations for \"Passw0rd\"");
    }
}

// Output:
// 1 violation for "password"
// 0 violations for "Passw0rd"

import jakarta.validation.Validation;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Null;

interface OnCreate { }
interface OnUpdate { }

class Customer {
    @Null(groups = OnCreate.class)                      // must not be set when creating
    @NotBlank(groups = OnUpdate.class)                  // must be set when updating
    String id;

    @NotBlank(groups = {OnCreate.class, OnUpdate.class})
    String name;

    Customer(String id, String name) { this.id = id; this.name = name; }
}

class Demo {
    public static void main(String[] args) {
        var validator = Validation.buildDefaultValidatorFactory().getValidator();

        System.out.println("create without id: " + validator.validate(new Customer(null, "Asha"), OnCreate.class).size() + " violations");
        System.out.println("create with an id: " + validator.validate(new Customer("c1", "Asha"), OnCreate.class).size() + " violation");
        System.out.println("update without id: " + validator.validate(new Customer(null, "Asha"), OnUpdate.class).size() + " violation");
    }
}

// Output:
// create without id: 0 violations
// create with an id: 1 violation
// update without id: 1 violation

