import org.junit.jupiter.api.Test;
import org.junit.platform.launcher.core.LauncherDiscoveryRequestBuilder;
import org.junit.platform.launcher.core.LauncherFactory;
import org.junit.platform.launcher.listeners.SummaryGeneratingListener;
import org.junit.platform.engine.discovery.DiscoverySelectors;
import static org.assertj.core.api.Assertions.assertThat;

class Calculator {
    int add(int a, int b) { return a + b; }
    int divide(int a, int b) { return a / b; }
}

class CalculatorTest {
    @Test
    void addsTwoNumbers() {
        assertThat(new Calculator().add(2, 3)).isEqualTo(5);
    }

    @Test
    void divides() {
        assertThat(new Calculator().divide(10, 2)).isEqualTo(5).isPositive();
    }
}

class Demo {
    static void run(Class<?> testClass) {
        SummaryGeneratingListener listener = new SummaryGeneratingListener();
        LauncherFactory.create().execute(LauncherDiscoveryRequestBuilder.request()
                .selectors(DiscoverySelectors.selectClass(testClass)).build(), listener);
        var summary = listener.getSummary();
        System.out.println(testClass.getSimpleName() + ": " + summary.getTestsSucceededCount() + " passed, " + summary.getTestsFailedCount() + " failed");
    }

    public static void main(String[] args) {
        run(CalculatorTest.class);
    }
}

// Output:
// CalculatorTest: 2 passed, 0 failed

