class Account {
    private int balance;
    void deposit(int amount) { balance += amount; }
    void withdraw(int amount) {
        if (amount > balance) throw new IllegalStateException("insufficient funds");
        balance -= amount;
    }
    int balance() { return balance; }
}

class AccountTest {
    Account account;

    @BeforeEach
    void setUp() {                                            // runs before every test
        account = new Account();
        account.deposit(100);
    }

    @Test
    void withdrawReducesBalance() {
        account.withdraw(30);
        assertThat(account.balance()).isEqualTo(70);
    }

    @Test
    void cannotWithdrawMoreThanBalance() {
        var error = assertThrows(IllegalStateException.class, () -> account.withdraw(500));
        assertThat(error).hasMessage("insufficient funds");
    }
}

