import java.util.ArrayList;
import java.util.List;
import jakarta.persistence.CascadeType;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Entity
class Author {
    @Id @GeneratedValue Long id;
    String name;

    @OneToMany(mappedBy = "author", cascade = CascadeType.ALL)       // "author" in Book owns the foreign key
    List<Book> books = new ArrayList<>();

    protected Author() { }
    Author(String name) { this.name = name; }

    void add(Book book) { books.add(book); book.author = this; }     // keep both sides in sync
}

@Entity
class Book {
    @Id @GeneratedValue Long id;
    String title;

    @ManyToOne(fetch = FetchType.LAZY)
    Author author;

    protected Book() { }
    Book(String title) { this.title = title; }
}

interface AuthorRepository extends JpaRepository<Author, Long> { }

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            AuthorRepository repository = context.getBean(AuthorRepository.class);
            TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));

            Author author = new Author("Tagore");
            author.add(new Book("Gitanjali"));
            author.add(new Book("The Home and the World"));
            repository.save(author);                                  // the cascade saves both books

            tx.executeWithoutResult(status -> {
                Author loaded = repository.findAll().get(0);
                System.out.println(loaded.name + " wrote " + loaded.books.size() + " books");
            });
        }
    }
}

// Output:
// Tagore wrote 2 books

