import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import org.hibernate.SessionFactory;
import org.hibernate.stat.Statistics;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Entity
class Author {
    @Id @GeneratedValue Long id;
    String name;
    @OneToMany(mappedBy = "author", cascade = CascadeType.ALL)
    List<Book> books = new ArrayList<>();
    protected Author() { }
    Author(String name) { this.name = name; }
}

@Entity
class Book {
    @Id @GeneratedValue Long id;
    String title;
    @ManyToOne(fetch = FetchType.LAZY) Author author;
    protected Book() { }
    Book(String title, Author author) { this.title = title; this.author = author; }
}

interface AuthorRepository extends JpaRepository<Author, Long> { }

@SpringBootApplication
class Demo {
    static Statistics seed(ConfigurableApplicationContext context, AuthorRepository authors) {
        TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));
        tx.executeWithoutResult(status -> {
            for (int i = 1; i <= 3; i++) {                                  // 3 authors with 2 books each
                Author author = new Author("Author " + i);
                author.books.add(new Book("Book " + i + "a", author));
                author.books.add(new Book("Book " + i + "b", author));
                authors.save(author);
            }
        });
        Statistics statistics = context.getBean(EntityManagerFactory.class).unwrap(SessionFactory.class).getStatistics();
        statistics.setStatisticsEnabled(true);
        statistics.clear();                                                 // count only what happens next
        return statistics;
    }

    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            AuthorRepository authors = context.getBean(AuthorRepository.class);
            Statistics statistics = seed(context, authors);
            TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));

            tx.executeWithoutResult(status -> {
                for (Author author : authors.findAll()) {                   // 1 query for the authors
                    author.books.size();                                     // + 1 query per author for its books
                }
            });
            System.out.println("queries: " + statistics.getPrepareStatementCount());
        }
    }
}

// Output:
// queries: 4

