import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.stereotype.Service;

@Service
class PriceService {
    private final AtomicInteger databaseCalls = new AtomicInteger();
    public int databaseCallsCount() { return databaseCalls.get(); }

    @Cacheable("prices")
    public int priceOf(String sku) {
        databaseCalls.incrementAndGet();                      // stands for a slow query
        return sku.length() * 100;
    }
}

@SpringBootApplication
@EnableCaching
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            PriceService service = context.getBean(PriceService.class);
            service.priceOf("A-1");
            service.priceOf("A-1");                           // served from the cache
            service.priceOf("B-22");                          // a different key, so it runs
            System.out.println("database calls: " + service.databaseCallsCount());
        }
    }
}

// Output:
// database calls: 2

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.stereotype.Service;

@Service
class ProfileService {
    final Map<Integer, String> database = new HashMap<>(Map.of(1, "Asha"));
    private final AtomicInteger reads = new AtomicInteger();
    public int readsCount() { return reads.get(); }

    @Cacheable("profiles")
    public String name(int id) { reads.incrementAndGet(); return database.get(id); }

    @CacheEvict(value = "profiles", key = "#id")              // drop the cached copy for this id
    public void rename(int id, String name) { database.put(id, name); }
}

@SpringBootApplication
@EnableCaching
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            ProfileService service = context.getBean(ProfileService.class);
            System.out.println(service.name(1));
            System.out.println(service.name(1) + " (cached)");
            service.rename(1, "Asha K");
            System.out.println(service.name(1) + " (fresh after evict)");
            System.out.println("database reads: " + service.readsCount());
        }
    }
}

// Output:
// Asha
// Asha (cached)
// Asha K (fresh after evict)
// database reads: 2

import java.util.concurrent.atomic.AtomicInteger;
