@Service
class CouponService {
    private final AtomicInteger lookups = new AtomicInteger();
    public int lookupsCount() { return lookups.get(); }

    @Cacheable(value = "coupons", key = "#code.toUpperCase()", unless = "#result == null")
    public Integer discountFor(String code) {
        lookups.incrementAndGet();
        return code.equalsIgnoreCase("save10") ? 10 : null;   // unknown codes give null
    }
}

@SpringBootApplication
@EnableCaching
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            CouponService service = context.getBean(CouponService.class);
            service.discountFor("save10");
            service.discountFor("SAVE10");                    // same key after upper-casing: cached
            service.discountFor("nope");
            service.discountFor("nope");                      // null is not stored, so it runs again
            System.out.println("lookups: " + service.lookupsCount());
        }
    }
}

