import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
class TransferService {
    private final JdbcTemplate jdbc;
    TransferService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional
    public void transfer(int from, int to, int amount, boolean crash) {
        jdbc.update("update account set balance = balance - ? where id = ?", amount, from);
        if (crash) throw new IllegalStateException("crash after the debit");      // everything above is undone
        jdbc.update("update account set balance = balance + ? where id = ?", amount, to);
    }

    public String balances() {
        return jdbc.queryForObject("select group_concat(balance order by id) from account", String.class);
    }
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            JdbcTemplate jdbc = context.getBean(JdbcTemplate.class);
            jdbc.execute("create table account (id int primary key, balance int)");
            jdbc.update("insert into account values (1, 100), (2, 0)");
            TransferService service = context.getBean(TransferService.class);

            try {
                service.transfer(1, 2, 40, true);
            } catch (IllegalStateException e) {
                System.out.println("failed: " + e.getMessage());
            }
            System.out.println("after the failure: " + service.balances());
            service.transfer(1, 2, 40, false);
            System.out.println("after a success:   " + service.balances());
        }
    }
}

// Output:
// failed: crash after the debit
// after the failure: 100,0
// after a success:   60,40

import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
class PaymentService {
    private final JdbcTemplate jdbc;
    PaymentService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional
    public void chargeDefault(int id) throws Exception {
        jdbc.update("update wallet set balance = balance - 10 where id = ?", id);
        throw new Exception("checked failure");                  // no rollback by default
    }

    @Transactional(rollbackFor = Exception.class)
    public void chargeSafely(int id) throws Exception {
        jdbc.update("update wallet set balance = balance - 10 where id = ?", id);
        throw new Exception("checked failure");                  // rolled back
    }

    public int balance(int id) { return jdbc.queryForObject("select balance from wallet where id = ?", Integer.class, id); }
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            JdbcTemplate jdbc = context.getBean(JdbcTemplate.class);
            jdbc.execute("create table wallet (id int primary key, balance int)");
            jdbc.update("insert into wallet values (1, 100)");
            PaymentService service = context.getBean(PaymentService.class);

            try { service.chargeDefault(1); } catch (Exception ignored) { }
            System.out.println("after the default rule:   " + service.balance(1));
            try { service.chargeSafely(1); } catch (Exception ignored) { }
            System.out.println("after rollbackFor:        " + service.balance(1));
        }
    }
}

// Output:
// after the default rule:   90
// after rollbackFor:        90

import org.springframework.boot.WebApplicationType;
