import org.springframework.transaction.annotation.Transactional;

@Service
class AuditService {
    private final JdbcTemplate jdbc;
    AuditService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional(propagation = Propagation.REQUIRES_NEW)       // its own transaction, committed on its own
    public void record(String message) { jdbc.update("insert into audit values (?)", message); }
}

@Service
class OrderService {
    private final JdbcTemplate jdbc;
    private final AuditService audit;
    OrderService(JdbcTemplate jdbc, AuditService audit) { this.jdbc = jdbc; this.audit = audit; }

    @Transactional
    public void place(String item) {
        jdbc.update("insert into orders values (?)", item);
        audit.record("tried to place " + item);
        throw new IllegalStateException("payment declined");     // rolls back the order only
    }
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            JdbcTemplate jdbc = context.getBean(JdbcTemplate.class);
            jdbc.execute("create table orders (item varchar(20))");
            jdbc.execute("create table audit (message varchar(50))");

            try { context.getBean(OrderService.class).place("pen"); } catch (IllegalStateException ignored) { }
            System.out.println("orders: " + jdbc.queryForObject("select count(*) from orders", Integer.class));
            System.out.println("audit:  " + jdbc.queryForObject("select count(*) from audit", Integer.class));
        }
    }
}

