import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
class ImportService {
    private final JdbcTemplate jdbc;
    ImportService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public void importAll(String name) {
        saveAndFail(name);                                        // a plain call inside the class: no proxy, no transaction
    }

    @Transactional
    public void saveAndFail(String name) {
        jdbc.update("insert into records values (?)", name);
        throw new IllegalStateException("boom");
    }
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            JdbcTemplate jdbc = context.getBean(JdbcTemplate.class);
            jdbc.execute("create table records (name varchar(20))");
            ImportService service = context.getBean(ImportService.class);

            try { service.saveAndFail("direct"); } catch (IllegalStateException ignored) { }   // through the proxy
            try { service.importAll("indirect"); } catch (IllegalStateException ignored) { }   // inside the class

            System.out.println(jdbc.queryForList("select name from records", String.class));
        }
    }
}

// Output:
// [indirect]

