            JdbcTemplate jdbc = context.getBean(JdbcTemplate.class);
            jdbc.execute("create table notes (text varchar(20))");
            TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));

            tx.executeWithoutResult(status -> jdbc.update("insert into notes values ('kept')"));

            tx.executeWithoutResult(status -> {
                jdbc.update("insert into notes values ('discarded')");
                status.setRollbackOnly();                         // undo this transaction without throwing
            });

            System.out.println(jdbc.queryForList("select text from notes", String.class));
        }
    }
}

