import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.data.jpa.repository.JpaRepository;

@Entity
class Item {
    @Id @GeneratedValue Long id;
    int stock;
    @Version Long version;                                    // incremented on every update
    protected Item() { }
    Item(int stock) { this.stock = stock; }
}

interface ItemRepository extends JpaRepository<Item, Long> { }

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            ItemRepository repository = context.getBean(ItemRepository.class);
            Long id = repository.save(new Item(10)).id;

            Item first = repository.findById(id).orElseThrow();       // two users load the same row
            Item second = repository.findById(id).orElseThrow();

            first.stock = 8;
            repository.save(first);                                   // succeeds, the version moves to 1

            second.stock = 5;
            try {
                repository.save(second);                              // still holds version 0
            } catch (OptimisticLockingFailureException e) {
                System.out.println("second update rejected");
            }
            System.out.println("stock in the database: " + repository.findById(id).orElseThrow().stock);
        }
    }
}

// Output:
// second update rejected
// stock in the database: 8

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.Version;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.data.jpa.repository.JpaRepository;

@Entity
class Counter {
    @Id @GeneratedValue Long id;
    int total;
    @Version Long version;
    protected Counter() { }
    Counter(int total) { this.total = total; }
}

interface CounterRepository extends JpaRepository<Counter, Long> { }

@SpringBootApplication
class Demo {
    static int incrementWithRetry(CounterRepository repository, Long id, boolean interfere) {
        for (int attempt = 1; attempt <= 3; attempt++) {
            Counter counter = repository.findById(id).orElseThrow();             // always start from fresh data
            if (interfere && attempt == 1) {                                     // simulate another user saving first
                Counter other = repository.findById(id).orElseThrow();
                other.total += 100;
                repository.save(other);
            }
            counter.total += 1;
            try {
                repository.save(counter);
                return attempt;
            } catch (OptimisticLockingFailureException e) {
                // someone else won; loop and try again with the new version
            }
        }
        throw new IllegalStateException("too many conflicts");
    }

    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            CounterRepository repository = context.getBean(CounterRepository.class);
            Long id = repository.save(new Counter(0)).id;

            int attempts = incrementWithRetry(repository, id, true);
            System.out.println("succeeded on attempt " + attempts);
            System.out.println("final value: " + repository.findById(id).orElseThrow().total);
        }
    }
}

// Output:
// succeeded on attempt 2
// final value: 101

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import jakarta.persistence.LockModeType;
import java.util.Optional;
import org.springframework.boot.WebApplicationType;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@Entity
class Seat {
    @Id @GeneratedValue Long id;
    boolean booked;
    protected Seat() { }
    Seat(boolean booked) { this.booked = booked; }
}

interface SeatRepository extends JpaRepository<Seat, Long> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)                     // SELECT ... FOR UPDATE
    @Query("select s from Seat s where s.id = :id")
    Optional<Seat> findForBooking(@Param("id") Long id);
}

@SpringBootApplication
class Demo {
    public static void main(String[] args) {
        try (ConfigurableApplicationContext context = new SpringApplicationBuilder(Demo.class).web(WebApplicationType.NONE).run(args)) {
            SeatRepository repository = context.getBean(SeatRepository.class);
            TransactionTemplate tx = new TransactionTemplate(context.getBean(PlatformTransactionManager.class));
            Long id = repository.save(new Seat(false)).id;

            tx.executeWithoutResult(status -> {
                Seat seat = repository.findForBooking(id).orElseThrow();   // the row is locked until this transaction ends
                if (!seat.booked) {
                    seat.booked = true;                                    // nobody else can book it meanwhile
                    System.out.println("seat booked");
                }
            });
            System.out.println("booked now: " + repository.findById(id).orElseThrow().booked);
        }
    }
}

// Output:
// seat booked
// booked now: true
